/bin/bash -lc "python - << 'PY'
import numpy as np
from sklearn.pipeline import Pipeline
from sklearn.preprocessing import StandardScaler
from sklearn.linear_model import LogisticRegression
from sklearn.discriminant_analysis import LinearDiscriminantAnalysis
from sklearn.svm import LinearSVC
from sklearn.ensemble import RandomForestClassifier
from sklearn.metrics import accuracy_score
from sklearn.model_selection import StratifiedKFold, cross_val_score

tr=np.load('/app/data/train_labeled.npz',allow_pickle=False)
va=np.load('/app/data/val_labeled.npz',allow_pickle=False)
Xtr=tr['counts']; ytr=tr['stim_class']
Xva=va['counts']; yva=va['stim_class']

# check label/orientation consistency
ori_to_cls={0:0,45:1,90:2,135:3,180:4,225:5,270:6,315:7}
mis_tr=np.sum(np.array([ori_to_cls.get(int(o),-1) for o in tr['orientation_deg']])"'!=ytr)
mis_va=np.sum(np.array([ori_to_cls.get(int(o),-1) for o in va['"'orientation_deg']])"'!=yva)
print('"'label mismatches train,val',mis_tr,mis_va)

# feature sets

def feats_flat(X):
    return X.reshape(len(X),-1)

def feats_unit_sum(X):
    return X.sum(axis=2)

def feats_time_sum(X):
    return X.sum(axis=1)

def feats_combo(X):
    return np.hstack([X.reshape(len(X),-1),X.sum(axis=2),X.sum(axis=1)])

feat_fns={'flat':feats_flat,'unit_sum':feats_unit_sum,'time_sum':feats_time_sum,'combo':feats_combo}

models={
'logreg':lambda:Pipeline([('sc',StandardScaler()),('clf',LogisticRegression(max_iter=5000,multi_class='multinomial',C=1.0))]),
'logreg_l1':lambda:Pipeline([('sc',StandardScaler()),('clf',LogisticRegression(max_iter=5000,penalty='l1',solver='saga',multi_class='multinomial',C=0.5))]),
'lda':lambda:Pipeline([('sc',StandardScaler()),('clf',LinearDiscriminantAnalysis())]),
'linearsvc':lambda:Pipeline([('sc',StandardScaler()),('clf',LinearSVC(C=1.0))]),
'rf':lambda:RandomForestClassifier(n_estimators=400,random_state=0)
}

skf=StratifiedKFold(n_splits=5,shuffle=True,random_state=0)
rows=[]
for fname,ff in feat_fns.items():
    Xtrf=ff(Xtr); Xvaf=ff(Xva)
    for mname,mk in models.items():
        m=mk()
        m.fit(Xtrf,ytr)
        val_acc=accuracy_score(yva,m.predict(Xvaf))
        cv=cross_val_score(m,Xtrf,ytr,cv=skf,scoring='accuracy')
        rows.append((val_acc,cv.mean(),cv.std(),fname,mname))

rows=sorted(rows,reverse=True)
for r in rows[:20]:
    print(r)
PY"
